function photoFor(product) {
  const filename = PRODUCT_IMAGE_FILES[product.id];
  return filename ? `img/${filename}` : (ASSETS[product.image] || ASSETS['burger-classic']);
}

const getById = (id) => document.getElementById(id);
const escapeHTML = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (value) => 'S/ ' + Number(value).toFixed(2);
const allProducts = MENU.flatMap(group => group.products.map(product => ({...product,category:group.title})));
const byId = new Map(allProducts.map(product => [product.id,product]));
const available = product => product.available !== false;
const storageKey = 'dmemo-fastfood-cart-v1';
let cart = [];
let modalProduct = null;
let modalQty = 1;
let modalExtras = {};
let search = '';
let toastTimer;

function loadCart() {
  try {
    const data = JSON.parse(localStorage.getItem(storageKey) || '[]');
    if (!Array.isArray(data)) return;
    cart = data.filter(item => item && byId.has(item.id) && available(byId.get(item.id)) && Number.isInteger(item.qty) && item.qty > 0 && item.qty <= 99)
      .map(item => ({
        id:item.id, qty:item.qty,
        creams:Array.isArray(item.creams)?item.creams.filter(c=>CREAMS.includes(c)):[],
        wingSauce:WING_SAUCES.includes(item.wingSauce)?item.wingSauce:'',
        variant:typeof item.variant==='string' && byId.get(item.id).variants?.includes(item.variant)?item.variant:'',
        extras:Array.isArray(item.extras) && byId.get(item.id).extras ? item.extras.filter(x=>BURGER_EXTRAS.some(e=>e.id===x.id) && Number.isInteger(x.qty) && x.qty>=1 && x.qty<=10).map(x=>({id:x.id,qty:x.qty})) : [],
        notes:typeof item.notes==='string'?item.notes.slice(0,260):''
      }));
  } catch (_) { cart = []; }
}
function saveCart() { try { localStorage.setItem(storageKey,JSON.stringify(cart)); } catch (_) {} }
function extrasPrice(item) { return (item.extras||[]).reduce((sum,x)=>sum+(BURGER_EXTRAS.find(e=>e.id===x.id)?.price||0)*x.qty,0); }
function unitPrice(item) { return byId.get(item.id).price + extrasPrice(item); }
function totalPrice() { return cart.reduce((sum,item)=>sum+unitPrice(item)*item.qty,0); }
function totalCount() { return cart.reduce((sum,item)=>sum+item.qty,0); }
function itemKey(item) { return JSON.stringify([item.id,[...(item.creams||[])].sort(),item.wingSauce||'',item.variant||'',item.extras||[],item.notes||'']); }
function showToast(message) {
  const toast = getById('toast');toast.textContent=message;
  toast.classList.add('show');clearTimeout(toastTimer);
  toastTimer=setTimeout(()=>toast.classList.remove('show'),2600);
}

function productCard(p) {
  return `<article class="product-card">
    <div class="product-photo"><img src="${photoFor(p)}" alt="${escapeHTML(p.name)}" loading="lazy" width="400" height="274"><span class="photo-badge">DMEMO</span></div>
    <div class="product-info"><h4>${escapeHTML(p.name)}</h4><p class="product-desc">${escapeHTML(p.desc)}</p><div class="product-bottom"><strong class="price">${money(p.price)}</strong><button class="add-btn" type="button" data-product="${p.id}" aria-label="Personalizar y agregar ${escapeHTML(p.name)}"><svg><use href="#ico-plus"/></svg></button></div></div>
  </article>`;
}
function renderNav() {
  getById('categoryNav').innerHTML = `<button class="category-chip active" type="button" data-category="all">Todos</button>` + MENU.map(g=>`<button type="button" class="category-chip" data-category="${g.id}">${g.emoji} ${g.title}</button>`).join('');
  getById('totalProducts').textContent=allProducts.filter(available).length+' platos y bebidas';
}
function renderMenu(category='all') {
  const term=search.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  let html='';let shown=0;
  for(const group of MENU) {
    if (category!=='all' && category!==group.id) continue;
    const filtered = group.products.filter(p => available(p) && (!term || `${p.name} ${p.desc} ${group.title}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(term)));
    if(!filtered.length) continue;
    shown+=filtered.length;
    let cards='';
    if(group.id==='bebidas') {
      for (const sub of ['Gaseosas','Jugos','Bebidas naturales']) {
        const match=filtered.filter(p=>p.section===sub);
        if(match.length) cards+=`<h4 class="subcategory-title">${sub}</h4><div class="product-grid">${match.map(productCard).join('')}</div>`;
      }
    } else { cards=`<div class="product-grid">${filtered.map(productCard).join('')}</div>`; }
    html+=`<section class="catalog-category" id="cat-${group.id}"><div class="category-heading"><div class="category-title"><span class="category-emoji">${group.emoji}</span><h3>${group.title}</h3></div><span class="category-count">${filtered.length} opciones</span></div>${cards}</section>`;
  }
  getById('menuRoot').innerHTML=html;
  getById('noResults').hidden=shown>0;
}
function setActiveChip(id) { document.querySelectorAll('.category-chip').forEach(btn=>btn.classList.toggle('active',btn.dataset.category===id)); }

function extraList() {
  return `<div class="option-block"><h3>Adicionales para tu hamburguesa</h3><p>Opcionales. Se suman automáticamente al precio.</p>`+BURGER_EXTRAS.map(x=>`<div class="extra-row"><div class="extra-name">${escapeHTML(x.name)}<small>+ ${money(x.price)} por unidad</small></div><div class="extra-stepper"><button type="button" data-extra-minus="${x.id}" aria-label="Quitar ${escapeHTML(x.name)}">−</button><output data-extra-count="${x.id}">0</output><button type="button" data-extra-plus="${x.id}" aria-label="Agregar ${escapeHTML(x.name)}">+</button></div></div>`).join('')+'</div>';
}
function creamsList() { return `<div class="option-block"><h3>Elige tus cremas</h3><p>Puedes seleccionar varias. La carta no indica un recargo por crema.</p><div class="pill-options">`+CREAMS.map(c=>`<label class="pill-option"><input type="checkbox" name="cream" value="${c}"><span>${c}</span></label>`).join('')+'</div></div>'; }
function wingsList() { return `<div class="option-block"><h3>Elige tu salsa de alitas *</h3><p>Selecciona una salsa para tu plato.</p><div class="pill-options">`+WING_SAUCES.map(c=>`<label class="pill-option"><input type="radio" name="wingSauce" value="${c}"><span>${c}</span></label>`).join('')+'</div></div>'; }
function variantsList(p) { return `<div class="option-block"><h3>Elige la bebida *</h3><p>Selecciona una opción.</p><div class="pill-options">`+p.variants.map(c=>`<label class="pill-option"><input type="radio" name="variant" value="${c}"><span>${escapeHTML(c)}</span></label>`).join('')+'</div></div>'; }
function openProduct(id) {
  const p=byId.get(id);if(!p || !available(p))return;
  modalProduct=p;modalQty=1;modalExtras={};
  getById('modalBody').innerHTML=`<img class="modal-photo" src="${photoFor(p)}" alt="${escapeHTML(p.name)}" width="400" height="274"><div class="modal-content"><span class="modal-overline">${escapeHTML(p.category)} · DMEMO</span><h2 id="modalTitle">${escapeHTML(p.name)}</h2><p class="modal-description">${escapeHTML(p.desc)}</p><div class="modal-price">${money(p.price)}</div>${p.wings?wingsList():''}${p.variants?variantsList(p):''}${p.creams?creamsList():''}${p.extras?extraList():''}<div class="option-block"><h3>Instrucciones especiales</h3><textarea id="modalNotes" class="modal-notes" maxlength="260" placeholder="Ej. Sin cebolla, papas crocantes... (opcional)"></textarea></div><div class="modal-quantity"><label>Cantidad</label><div class="modal-qty"><button type="button" id="modalQtyMinus" aria-label="Disminuir cantidad">−</button><span id="modalQtyValue">1</span><button type="button" id="modalQtyPlus" aria-label="Aumentar cantidad">+</button></div></div><button type="button" class="btn btn-yellow btn-block modal-add" id="modalAdd"><span>AGREGAR AL CARRITO</span><strong id="modalTotal" class="modal-add-price">${money(p.price)}</strong></button></div>`;
  getById('productDialog').showModal();
}
function updateModalTotal() {
  if (!modalProduct)return;
  const extraTotal=BURGER_EXTRAS.reduce((sum,e)=>sum+(modalExtras[e.id]||0)*e.price,0);
  getById('modalTotal').textContent=money((modalProduct.price+extraTotal)*modalQty);
  getById('modalQtyValue').textContent=modalQty;
  getById('modalBody').querySelectorAll('[data-extra-count]').forEach(el=>el.textContent=modalExtras[el.dataset.extraCount]||0);
}
function addModalProduct() {
  if (!modalProduct) return;
  const body=getById('modalBody');
  const wingSauce=body.querySelector('input[name="wingSauce"]:checked')?.value||'';
  const variant=body.querySelector('input[name="variant"]:checked')?.value||'';
  if(modalProduct.wings && !wingSauce){showToast('Selecciona una salsa para las alitas');return;}
  if(modalProduct.variants && !variant){showToast('Selecciona la bebida');return;}
  const item={id:modalProduct.id,qty:modalQty,creams:Array.from(body.querySelectorAll('input[name="cream"]:checked')).map(input=>input.value),wingSauce,variant,extras:BURGER_EXTRAS.filter(e=>modalExtras[e.id]>0).map(e=>({id:e.id,qty:modalExtras[e.id]})),notes:getById('modalNotes').value.trim().slice(0,260)};
  const matched=cart.find(other=>itemKey(other)===itemKey(item));
  if(matched)matched.qty=Math.min(99,matched.qty+item.qty);else cart.push(item);
  saveCart();renderCart();getById('productDialog').close();showToast('✓ Agregado a tu pedido');
}
function itemDetails(item) {
  const parts=[];
  if(item.variant)parts.push(item.variant);
  if(item.wingSauce)parts.push('Salsa: '+item.wingSauce);
  if(item.creams?.length)parts.push('Cremas: '+item.creams.join(', '));
  const extras=(item.extras||[]).map(x=>{const e=BURGER_EXTRAS.find(y=>y.id===x.id);return `${x.qty} × ${e?.name||''}`;});
  if(extras.length)parts.push('Adicionales: '+extras.join(', '));
  if(item.notes)parts.push('Nota: '+item.notes);
  return parts;
}
function renderCart() {
  const count=totalCount(),total=totalPrice();
  getById('headerCount').textContent=count;getById('floatingCount').textContent=count;
  getById('floatingTotal').textContent=money(total);getById('cartTitleCount').textContent=`(${count})`;
  getById('cartSubtotal').textContent=money(total);getById('checkoutTotal').textContent=money(total);
  getById('checkoutBtn').disabled=!cart.length;
  if(!cart.length){getById('cartItems').innerHTML='<div class="empty-cart"><div class="empty-icon"><svg><use href="#ico-bag"/></svg></div><h3>Tu carrito está vacío</h3><p>Elige tus favoritos y empieza a armar tu pedido.</p><button class="btn btn-yellow" type="button" data-keep-shopping>Explorar la carta</button></div>';return;}
  getById('cartItems').innerHTML=cart.map((item,i)=>{
    const p=byId.get(item.id);
    return `<div class="cart-item"><img src="${photoFor(p)}" alt="${escapeHTML(p.name)}" loading="lazy"><div><h3 class="cart-item-name">${escapeHTML(p.name)}</h3><p class="cart-item-details">${itemDetails(item).map(escapeHTML).join('<br>')||'Sin personalizaciones'}</p><strong class="cart-item-unit">${money(unitPrice(item)*item.qty)}</strong><div class="cart-item-actions"><div class="qty-mini"><button data-cart-minus="${i}" type="button" aria-label="Disminuir ${escapeHTML(p.name)}">−</button><span>${item.qty}</span><button data-cart-plus="${i}" type="button" aria-label="Aumentar ${escapeHTML(p.name)}">+</button></div><button class="remove-item" data-cart-remove="${i}" type="button">Quitar</button></div></div></div>`;
  }).join('');
}
function openCart() {
  getById('drawerBackdrop').hidden=false;
  getById('cartDrawer').classList.add('open');getById('cartDrawer').setAttribute('aria-hidden','false');
  document.body.style.overflow='hidden';getById('closeCart').focus();
}
function closeCart() {
  getById('cartDrawer').classList.remove('open');getById('cartDrawer').setAttribute('aria-hidden','true');getById('drawerBackdrop').hidden=true;
  document.body.style.overflow='';
}
function showCheckout() {
  if(!cart.length)return;
  getById('cartListView').hidden=true;getById('checkoutView').hidden=false;
  getById('cartTitle').firstChild.textContent='FINALIZAR PEDIDO ';
  getById('checkoutError').hidden=true;
  getById('checkoutView').scrollTop=0;
}
function showCartList() {
  getById('cartListView').hidden=false;getById('checkoutView').hidden=true;
  getById('cartTitle').firstChild.textContent='TU PEDIDO ';
}
function updateDeliveryFields() {
  const mode=document.querySelector('input[name="deliveryMode"]:checked')?.value||'delivery';
  const isDelivery=mode==='delivery';
  getById('deliveryFields').hidden=!isDelivery;
  getById('pickupFields').hidden=isDelivery;
  getById('deliveryDistrict').required=isDelivery;getById('deliveryAddress').required=isDelivery;
  getById('pickupTime').required=!isDelivery;
}
function setupPickupMin() {
  const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());
  getById('pickupTime').min=now.toISOString().slice(0,16);
}
function formDataText() {
  const name=getById('clientName').value.trim();
  const phone=getById('clientPhone').value.replace(/\D/g,'');
  const mode=document.querySelector('input[name="deliveryMode"]:checked')?.value||'delivery';
  const method=document.querySelector('input[name="paymentMethod"]:checked')?.value||'';
  if(name.length<3) return {error:'Ingresa tu nombre completo.'};
  if(phone.length<9 || phone.length>12) return {error:'Ingresa un número de celular válido.'};
  let deliveryText='';
  if(mode==='delivery'){
    const district=getById('deliveryDistrict').value.trim(),address=getById('deliveryAddress').value.trim(),reference=getById('deliveryReference').value.trim();
    if(!district || !address)return {error:'Completa el distrito y la dirección de entrega.'};
    deliveryText=`🚴 *Modalidad:* Delivery\n📍 *Distrito:* ${district}\n🏠 *Dirección:* ${address}${reference?'\n📌 *Referencia:* '+reference:''}\n🚚 *Costo de envío:* Por confirmar`;
  } else {
    const pickup=getById('pickupTime').value;
    if(!pickup)return {error:'Selecciona la fecha y hora de recojo.'};
    const pickupDate=new Date(pickup);
    if(!Number.isFinite(pickupDate.getTime()) || pickupDate.getTime()<Date.now()-60000)return {error:'Elige una fecha y hora de recojo futuras.'};
    const formatted=pickupDate.toLocaleString('es-PE',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true});
    deliveryText=`🏪 *Modalidad:* ${mode==='recojo'?'Recojo en tienda':'Preparar para recojo'}\n📍 *Sede:* ${CONFIG.address}\n🕒 *Hora solicitada:* ${formatted}`;
  }
  if(!method)return {error:'Selecciona un método de pago.'};
  const lines=cart.map((item,i)=>{
    const p=byId.get(item.id);
    const details=itemDetails(item).map(d=>'   • '+d).join('\n');
    return `${i+1}. *${item.qty} × ${p.name}* — ${money(unitPrice(item)*item.qty)}\n   Precio por unidad: ${money(unitPrice(item))}${details?'\n'+details:''}`;
  }).join('\n\n');
  const comment=getById('orderNotes').value.trim().slice(0,400);
  const msg=`🍔 *NUEVO PEDIDO — DMEMO FAST FOOD*\n\n👤 *Cliente:* ${name}\n📱 *Celular:* ${phone}\n\n🛒 *DETALLE DEL PEDIDO*\n${lines}\n\n💰 *Subtotal:* ${money(totalPrice())}\n${deliveryText}\n💳 *Pago:* ${method}${comment?'\n📝 *Observaciones:* '+comment:''}\n\nPor favor, confírmenme la disponibilidad, el total final y los datos de pago. ¡Gracias!`;
  return {message:msg};
}

function init() {
  getById('brandLogo').src=ASSETS.logo;
  getById('heroFood').src=ASSETS['burger-bestia'];
  getById('year').textContent=new Date().getFullYear();
  renderNav();renderMenu();loadCart();renderCart();setupPickupMin();
  getById('menuRoot').addEventListener('click',e=>{
    const btn=e.target.closest('[data-product]');if(btn)openProduct(btn.dataset.product);
  });
  getById('categoryNav').addEventListener('click',e=>{
    const btn=e.target.closest('[data-category]');if(!btn)return;
    const id=btn.dataset.category;setActiveChip(id);renderMenu(id);
    getById('menu').scrollIntoView({behavior:'smooth',block:'start'});
  });
  getById('searchInput').addEventListener('input',e=>{
    search=e.target.value;getById('clearSearch').hidden=!search;
    setActiveChip('all');renderMenu();
  });
  const reset=()=>{search='';getById('searchInput').value='';getById('clearSearch').hidden=true;setActiveChip('all');renderMenu();};
  getById('clearSearch').addEventListener('click',reset);
  getById('resetSearch').addEventListener('click',reset);
  getById('closeProduct').addEventListener('click',()=>getById('productDialog').close());
  getById('productDialog').addEventListener('click',e=>{if(e.target===getById('productDialog'))getById('productDialog').close();});
  getById('modalBody').addEventListener('click',e=>{
    const b=e.target.closest('button');if(!b)return;
    if(b.id==='modalQtyMinus')modalQty=Math.max(1,modalQty-1);
    else if(b.id==='modalQtyPlus')modalQty=Math.min(99,modalQty+1);
    else if(b.dataset.extraPlus){const k=b.dataset.extraPlus;modalExtras[k]=Math.min(10,(modalExtras[k]||0)+1);}
    else if(b.dataset.extraMinus){const k=b.dataset.extraMinus;modalExtras[k]=Math.max(0,(modalExtras[k]||0)-1);}
    else if(b.id==='modalAdd'){addModalProduct();return;}
    updateModalTotal();
  });
  [getById('openCartTop'),getById('floatingCart')].forEach(btn=>btn.addEventListener('click',openCart));
  [getById('closeCart'),getById('drawerBackdrop'),getById('keepShopping')].forEach(btn=>btn.addEventListener('click',closeCart));
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&getById('cartDrawer').classList.contains('open'))closeCart();});
  getById('cartItems').addEventListener('click',e=>{
    if(e.target.closest('[data-keep-shopping]')){closeCart();return;}
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.cartRemove!==undefined){cart.splice(Number(b.dataset.cartRemove),1);}
    else if(b.dataset.cartPlus!==undefined){const it=cart[Number(b.dataset.cartPlus)];if(it)it.qty=Math.min(99,it.qty+1);}
    else if(b.dataset.cartMinus!==undefined){const index=Number(b.dataset.cartMinus),it=cart[index];if(it){it.qty--;if(it.qty<1)cart.splice(index,1);}}
    else return;
    saveCart();renderCart();
  });
  getById('checkoutBtn').addEventListener('click',showCheckout);
  getById('backToCart').addEventListener('click',showCartList);
  document.querySelectorAll('input[name="deliveryMode"]').forEach(r=>r.addEventListener('change',updateDeliveryFields));
  updateDeliveryFields();
  getById('checkoutForm').addEventListener('submit',e=>{
    e.preventDefault();
    const result=formDataText();
    if(result.error){const el=getById('checkoutError');el.textContent=result.error;el.hidden=false;el.scrollIntoView({behavior:'smooth',block:'center'});return;}
    getById('checkoutError').hidden=true;
    const url=`https://wa.me/${CONFIG.whatsapp}?text=${encodeURIComponent(result.message)}`;
    // No se borra el carrito porque abrir WhatsApp NO garantiza que el mensaje se envió.
    const newWindow=window.open(url,'_blank','noopener,noreferrer');
    if(!newWindow){window.location.href=url;}
  });
}
